const sh = wb.getWorksheet('Sheet1');
let changed = 0;
for (let r = 3; r <= 26; r++) {
  const c = sh.getRange('B' + r);
  const v = c.getValues()[0][0];
  if (typeof v !== 'string') continue;
  const m = v.match(/\(([^)]*)\)/);
  if (!m) continue;
  c.setValue("'" + m[1]);
  changed++;
}
